// neon.test.js — behavioral suite for NÉON's collision and game rules.
//
// Pure logic only: `node --test`, no DOM, zero dependencies (see
// CONTRIBUTING.md). Covers the collision primitive, brick bounces (head-on,
// tunneling, sticky, seams, corners), paddle bounces (tunneling, capture,
// dead angle, speed), combo bounds, dt-independence and the life / level
// transitions.
//
// Run: `npm test`

import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  collides,
  step,
  tick,
  resolveBricks,
  makeBricks,
  createState,
  ballSpeed,
  comboMultiplier,
  scoreForBrick,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
  BALL_R,
  PADDLE_Y,
  PADDLE_H,
  UP,
  DOWN,
  LEFT,
  RIGHT,
} from './neon.js';

// --- Collision primitive ---------------------------------------------------

test('collides: clear overlap detected', () => {
  const ball = { x: 100, y: 100, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('collides: ball clearly away => no collision', () => {
  const ball = { x: 300, y: 300, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), false);
});

test('collides: edge contact (radius) detected', () => {
  const ball = { x: 85, y: 100, r: 8 }; // right edge of the ball at 93 > 90
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

// --- Walls -----------------------------------------------------------------

test('step: bounce off the left wall', () => {
  const state = createState(1);
  state.ball = { x: 2, y: 200, r: 7, vx: -300, vy: 0 };
  step(state, 1 / 60);
  assert.ok(state.ball.vx > 0, 'horizontal velocity should flip to the right');
});

test('step: ball exiting through the bottom => lost', () => {
  const state = createState(1);
  state.ball = { x: 320, y: belowField(), r: 7, vx: 0, vy: 400 };
  const lost = step(state, 1 / 60);
  assert.equal(lost, true);
});

// --- Grid ------------------------------------------------------------------

test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

// --- Bricks: bounce (defect: the ball plows straight through) --------------

test('bricks: head-on top hit bounces the ball back up', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball = {
    x: brick.x + brick.w / 2,
    y: brick.y - BALL_R + 4.5,
    r: BALL_R, vx: 0, vy: 300,
    px: brick.x + brick.w / 2, py: brick.y - BALL_R - 1,
  };
  const broken = resolveBricks(state);
  assert.equal(broken, 1);
  assert.equal(brick.alive, false);
  assert.equal(Math.sign(state.ball.vy), UP);
  assert.ok(state.ball.y + BALL_R <= brick.y, 'ball rests above the brick');
});

// Defect: tunneling. At level 8 one step is 44.5 px while brick height + ball
// diameter is 34 px: the ball lands fully below the brick, so only a swept
// test can see the crossing.
test('bricks: a fast ball crossing a whole brick in one step still bounces', () => {
  const state = createState(8);
  const brick = state.bricks[0];
  const speed = ballSpeed(8);
  state.ball = {
    x: brick.x + brick.w / 2,
    y: brick.y - BALL_R - 2,
    r: BALL_R, vx: 0, vy: speed,
    px: brick.x + brick.w / 2, py: brick.y - BALL_R - 2,
  };
  step(state, 0.05);
  assert.ok(
    state.ball.y - BALL_R > brick.y + brick.h,
    'discrete test alone would miss this brick',
  );
  const broken = resolveBricks(state);
  assert.equal(broken, 1);
  assert.equal(Math.sign(state.ball.vy), UP);
  assert.equal(state.ball.y, brick.y - BALL_R);
});

// Defect: sticky. A ball that ends the step inside a brick must be pushed out,
// otherwise it re-overlaps next frame and re-inverts forever.
test('bricks: a ball resting inside a brick is pushed out and bounces', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball = {
    x: brick.x + brick.w / 2,
    y: brick.y + 6,
    r: BALL_R, vx: 0, vy: 120,
    px: brick.x + brick.w / 2, py: brick.y + 6,
  };
  const broken = resolveBricks(state);
  assert.equal(broken, 1);
  assert.ok(!collides(state.ball, brick), 'ball is pushed out of the brick');
  assert.equal(Math.sign(state.ball.vy), UP);
  assert.equal(state.ball.y, brick.y - BALL_R);
});

// Defect: seam. The ball (diameter 14) straddles two vertically stacked bricks
// (gap 8) in one pass: two vy flips would cancel each other and the ball would
// go through. Expect exactly ONE flip per axis per pass.
test('bricks: two bricks straddled in one pass flip vy once, not twice', () => {
  const state = createState(1);
  const top = state.bricks[0];    // row 0: y 48..68
  const bottom = state.bricks[8]; // row 1: y 76..96 (same column)
  state.ball = {
    x: top.x + top.w / 2,
    y: 72, // straddling the 68..76 seam
    r: BALL_R, vx: 0, vy: -300,
    px: top.x + top.w / 2, py: 74,
  };
  const broken = resolveBricks(state);
  assert.equal(broken, 2);
  assert.equal(top.alive, false);
  assert.equal(bottom.alive, false);
  // Rising into the top brick's bottom face: one flip downward. A second flip
  // from the bottom brick would cancel it (vy back to -300).
  assert.equal(state.ball.vy, 300);
  assert.equal(state.ball.y, top.y + top.h + BALL_R);
});

// Defect: face vs corner. Equal penetration on both axes is a corner: BOTH
// components must invert.
test('bricks: corner hit inverts both components', () => {
  const state = createState(1);
  const brick = state.bricks[2]; // away from the walls
  state.ball = {
    x: brick.x + 6,
    y: brick.y + 6, // equal penetration on both axes
    r: BALL_R, vx: 100, vy: 300,
    px: brick.x + 6, py: brick.y + 6,
  };
  const broken = resolveBricks(state);
  assert.equal(broken, 1);
  assert.equal(Math.sign(state.ball.vx), LEFT);
  assert.equal(Math.sign(state.ball.vy), UP);
  assert.ok(!collides(state.ball, brick));
});

// --- Paddle (defects: tunneling, capture, dead angle, speed) ---------------

// Defect: paddle tunneling. At level 5 one step is 31 px while paddle height +
// ball diameter is 26 px: the discrete window test misses the paddle entirely.
test('paddle: a fast ball crossing the paddle in one step still bounces', () => {
  const state = createState(5);
  const speed = ballSpeed(5);
  state.ball = {
    x: WIDTH / 2,
    y: PADDLE_Y - BALL_R - 1,
    r: BALL_R, vx: 0, vy: speed,
    px: WIDTH / 2, py: PADDLE_Y - BALL_R - 1,
  };
  const lost = step(state, 0.05);
  assert.equal(lost, false);
  assert.equal(Math.sign(state.ball.vy), UP);
  assert.equal(state.ball.y, PADDLE_Y - BALL_R);
  assert.ok(Math.abs(Math.hypot(state.ball.vx, state.ball.vy) - speed) < 0.01);
});

// Defect: capture. A paddle teleported onto the ball must push it back out
// through the top, never let it sink through.
test('paddle: a ball trapped inside the paddle is pushed out through the top', () => {
  const state = createState(1);
  state.ball = {
    x: WIDTH / 2,
    y: PADDLE_Y + PADDLE_H / 2,
    r: BALL_R, vx: 0, vy: 200,
    px: WIDTH / 2, py: PADDLE_Y + PADDLE_H / 2,
  };
  const lost = step(state, 1 / 60);
  assert.equal(lost, false);
  assert.equal(Math.sign(state.ball.vy), UP);
  assert.equal(state.ball.y, PADDLE_Y - BALL_R);
});

// Defect: dead angle. A center hit (hit = 0) must keep a horizontal component,
// otherwise the ball loops vertically between paddle and ceiling forever.
test('paddle: a center hit never produces a vertical dead angle', () => {
  const state = createState(1);
  const speed = ballSpeed(1);
  state.ball = {
    x: WIDTH / 2,
    y: PADDLE_Y - BALL_R - 2,
    r: BALL_R, vx: 0, vy: 300,
    px: WIDTH / 2, py: PADDLE_Y - BALL_R - 2,
  };
  step(state, 1 / 60);
  assert.equal(Math.sign(state.ball.vy), UP);
  assert.ok(Math.abs(state.ball.vx) >= speed * 0.2, 'keeps a horizontal component');
});

// Defect: speed. The norm after a paddle bounce must be the level speed, not
// sqrt(vy_in^2 + (0.6*speed*hit)^2).
test('paddle: bounce preserves the level speed', () => {
  const state = createState(1);
  const speed = ballSpeed(1);
  state.ball = {
    x: WIDTH / 2 + 24, // hit = 0.5
    y: PADDLE_Y - BALL_R - 2,
    r: BALL_R, vx: 0, vy: 300,
    px: WIDTH / 2 + 24, py: PADDLE_Y - BALL_R - 2,
  };
  step(state, 1 / 60);
  const norm = Math.hypot(state.ball.vx, state.ball.vy);
  assert.ok(Math.abs(norm - speed) < 0.01, `speed ${norm} != ${speed}`);
});

// --- dt-independence -------------------------------------------------------

// A swept bounce lands at the exact face, whatever the step size: the result
// of a brick bounce is identical at 30 fps and at 144 fps.
test('dt-independence: a brick bounce lands identically at 30 fps and 144 fps', () => {
  const run = (dt) => {
    const s = createState(1);
    const b = s.bricks[0];
    s.ball = {
      x: b.x + b.w / 2,
      y: b.y - BALL_R - 2,
      r: BALL_R, vx: 0, vy: 300,
      px: b.x + b.w / 2, py: b.y - BALL_R - 2,
    };
    step(s, dt);
    resolveBricks(s);
    return { y: s.ball.y, vy: s.ball.vy };
  };
  assert.deepEqual(run(0.05), run(1 / 144));
});

// --- Score / combo / lives / transitions -----------------------------------

test('combo: multiplier is bounded', () => {
  assert.equal(comboMultiplier(0), 1);
  assert.equal(comboMultiplier(10), 4);
  assert.ok(comboMultiplier(100) <= 4);
});

test('bricks: a brick is broken and scored exactly once', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball = {
    x: brick.x + brick.w / 2,
    y: brick.y + 6,
    r: BALL_R, vx: 0, vy: 120,
    px: brick.x + brick.w / 2, py: brick.y + 6,
  };
  assert.equal(resolveBricks(state), 1);
  const scored = state.score;
  assert.equal(brick.alive, false);
  assert.equal(resolveBricks(state), 0, 'already dead: no double count');
  assert.equal(state.score, scored);
  assert.equal(scored, scoreForBrick(brick, 1));
});

test('lives & combo: one life lost per exit, combo reset, ball relaunched', () => {
  const state = createState(1);
  state.lives = 3;
  state.combo = 7;
  state.ball = {
    x: WIDTH / 2,
    y: belowField(),
    r: BALL_R, vx: 0, vy: 400,
    px: WIDTH / 2, py: belowField() - 10,
  };
  tick(state, 1 / 60);
  assert.equal(state.lives, 2);
  assert.equal(state.combo, 0);
