// Defect: transition. When the last brick is broken AND the last life is lost
// in the same tick, the cleared level must still advance (the old code reset
// the state first, then saw only fresh alive bricks, and never advanced).
test('transitions: last brick broken and last life lost in the same tick', () => {
  const state = createState(1);
  state.lives = 1;
  state.bricks.forEach((b, i) => { if (i !== 1) b.alive = false; });
  const brick = state.bricks[1];
  state.ball = {
    x: brick.x + brick.w / 2,
    y: 40,
    r: BALL_R, vx: 0, vy: 10000,
    px: brick.x + brick.w / 2, py: 40,
  };
  tick(state, 0.05);
  assert.equal(state.level, 2, 'the cleared level still advances');
  assert.equal(state.lives, 3, 'fresh game after the game over');
  assert.equal(state.bricks.length, BRICK_ROWS * BRICK_COLS);
