edits.newText:
// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit — resolveBricks() answers that with a swept test.
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// --- Brick collision (swept + discrete) ------------------------------------

// Swept test: does the segment (fx,fy)->(tx,ty) enter the rect
// (x0,y0)-(x1,y1)? Returns the earliest entry time t in (0,1] and the face
// that was crossed ('top' | 'bottom' | 'left' | 'right'), or null when there
// is no crossing (the ball started inside or never touched the rect).
function sweptEntry(fx, fy, tx, ty, x0, y0, x1, y1) {
  const dx = tx - fx;
  const dy = ty - fy;
  if (dx === 0 && dy === 0) return null;

  let tmin = 0;
  let tmax = 1;
  let face = null;

  if (dx === 0) {
    if (fx <= x0 || fx >= x1) return null;
  } else {
    const t1 = (x0 - fx) / dx;
    const t2 = (x1 - fx) / dx;
    const entry = Math.min(t1, t2);
    const exit = Math.max(t1, t2);
    if (entry > tmin) {
      tmin = entry;
      face = dx > 0 ? 'left' : 'right';
    }
    if (exit < tmax) tmax = exit;
  }

  if (dy === 0) {
    if (fy <= y0 || fy >= y1) return null;
  } else {
    const t1 = (y0 - fy) / dy;
    const t2 = (y1 - fy) / dy;
    const entry = Math.min(t1, t2);
    const exit = Math.max(t1, t2);
    if (entry > tmin) {
      tmin = entry;
      face = dy > 0 ? 'top' : 'bottom';
    }
    if (exit < tmax) tmax = exit;
  }

  if (tmin > tmax || tmin <= 0 || tmin > 1) return null;
  return { t: tmin, face };
}

// Resolves the ball against every live brick for this tick: breaks the bricks
// it touches, scores them, and bounces the ball off the face it hit. A swept
// test (ball.px/ball.py -> current position) catches fast balls that would
// otherwise tunnel through a brick in one step; a discrete fallback catches a
// ball already resting inside one (sticky case). At most ONE velocity flip per
// axis per pass, so a ball straddling a seam between two bricks never gets its
// two flips cancelled. Returns the number of bricks broken.
export function resolveBricks(state) {
  const { ball, bricks } = state;
  const fromX = Number.isFinite(ball.px) ? ball.px : ball.x;
  const fromY = Number.isFinite(ball.py) ? ball.py : ball.y;

  const hits = [];
  for (const brick of bricks) {
    if (!brick.alive) continue;
    const hit = sweptEntry(
      fromX, fromY, ball.x, ball.y,
      brick.x - ball.r, brick.y - ball.r,
      brick.x + brick.w + ball.r, brick.y + brick.h + ball.r,
    );
    if (hit) {
      hits.push({ brick, t: hit.t, face: hit.face, swept: true });
    } else if (collides(ball, brick)) {
      hits.push({ brick, t: Infinity, swept: false });
    }
  }
  hits.sort((a, b) => a.t - b.t);

  let flippedX = false;
  let flippedY = false;
  let broken = 0;

  for (const { brick, swept, face } of hits) {
    brick.alive = false;
    broken += 1;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);

    let axis; // 'x' | 'y' — the axis the bounce pushes along
    let dir;  // -1 pushes toward smaller coordinates, +1 toward larger
    if (swept) {
      if (face === 'top' || face === 'bottom') {
        axis = 'y';
        dir = face === 'top' ? -1 : 1;
      } else {
        axis = 'x';
        dir = face === 'left' ? -1 : 1;
      }
    } else {
      // Face vs corner, from the penetration depths: the axis with the smaller
      // penetration is the hit one; equal penetrations mean a corner.
      const penLeft = ball.x + ball.r - brick.x;
      const penRight = brick.x + brick.w - (ball.x - ball.r);
      const penTop = ball.y + ball.r - brick.y;
      const penBottom = brick.y + brick.h - (ball.y - ball.r);
      const penX = Math.min(penLeft, penRight);
      const penY = Math.min(penTop, penBottom);
      if (Math.abs(penX - penY) <= 0.5) {
        // Corner: invert both components and push out along both axes.
        if (!flippedX) { ball.vx = -ball.vx; flippedX = true; }
        if (!flippedY) { ball.vy = -ball.vy; flippedY = true; }
        ball.x += penLeft < penRight ? -penX : penX;
        ball.y += penTop < penBottom ? -penY : penY;
        continue;
      }
      if (penX < penY) {
        axis = 'x';
        dir = penLeft < penRight ? -1 : 1;
      } else {
        axis = 'y';
        dir = penTop < penBottom ? -1 : 1;
      }
    }

    if (axis === 'y' && !flippedY) {
      flippedY = true;
      ball.vy = dir < 0 ? -Math.abs(ball.vy) : Math.abs(ball.vy);
      ball.y = dir < 0 ? brick.y - ball.r : brick.y + brick.h + ball.r;
    } else if (axis === 'x' && !flippedX) {
      flippedX = true;
      ball.vx = dir < 0 ? -Math.abs(ball.vx) : Math.abs(ball.vx);
      ball.x = dir < 0 ? brick.x - ball.r : brick.x + brick.w + ball.r;
    }
  }

  // A side push can carry the ball past a wall: clamp it back and keep the
  // corresponding component pointing inward.
  if (ball.x < ball.r) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x > WIDTH - ball.r) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  return broken;
}

