// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls and the paddle. Brick bounces live in resolveBricks(), called by
// tick(). The previous position is kept on the ball (px/py) so the swept
// tests can see the whole segment of this step.
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  ball.px = ball.x;
  ball.py = ball.y;

  ball.x += ball.vx * dt;
