edits.newText:
// Paddle — swept test: the ball bounces the moment its bottom reaches the
// paddle's top plane, wherever along the step that happens. This catches
// fast balls that would jump the paddle in one step, and a paddle
// teleported onto the ball: the ball always comes back out through the top.
if (ball.vy > 0) {
  const planeY = paddle.y - ball.r;
  let hitX = ball.x;
  let bounce = false;

  const dy = ball.y - ball.py;
  if (dy > 0 && ball.py <= planeY && ball.y >= planeY) {
    const t = (planeY - ball.py) / dy;
    hitX = ball.px + (ball.x - ball.px) * t;
    bounce = hitX >= paddle.x && hitX <= paddle.x + paddle.w;
  }

  // Capture: the paddle moved onto the ball (mouse teleport). Push it out
  // through the top instead of letting it sink through the paddle.
  if (
    !bounce &&
    ball.x + ball.r > paddle.x && ball.x - ball.r < paddle.x + paddle.w &&
    ball.y + ball.r > paddle.y && ball.y - ball.r < paddle.y + paddle.h
  ) {
    bounce = true;
    hitX = ball.x;
  }

  if (bounce) {
    ball.y = planeY;
    // The rebound angle depends on where the paddle was hit.
    const hit = (hitX - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    const speed = ballSpeed(state.level);
    let vx = speed * 0.6 * hit;
    const maxVx = speed * 0.6;
    const minVx = speed * 0.2;
    vx = Math.max(-maxVx, Math.min(maxVx, vx));
    if (Math.abs(vx) < minVx) vx = (vx < 0 ? -1 : 1) * minVx; // no dead angle
    ball.vx = vx;
    // Keep the outgoing speed exactly at the level speed.
    ball.vy = -Math.sqrt(speed * speed - vx * vx);
    state.combo = 0; // touching the paddle resets the combo
  }
}

