// --- Game tick (pure bookkeeping) ------------------------------------------

// Advances the game by one tick: physics, brick collision, then the life and
// level bookkeeping. Pure (no DOM): storage is only touched when the state
// carries a `storage` handle (boot wires it; tests leave it off). Returns the
// number of bricks broken during this tick.
export function tick(state, dt) {
  const lost = step(state, dt);
  const broken = resolveBricks(state);
  const cleared = state.bricks.every((b) => !b.alive);

  if (lost) {
    state.lives -= 1;
    state.combo = 0;
    if (state.lives <= 0) {
      const storage = state.storage;
      if (storage) state.best = saveBest(storage, state.score);
      Object.assign(state, createState(state.level), { storage });
      if (storage) state.best = loadBest(storage);
    } else {
      // relaunch the ball
      state.ball = createState(state.level).ball;
    }
  }

  // Level cleared — even when the ball was lost in the same tick: the last
  // brick still counts and the level advances.
  if (cleared) {
    state.level += 1;
    state.bricks = makeBricks(state.level);
    state.ball = createState(state.level).ball;
  }

  return broken;
}

