import { createState, tick, ballSpeed, WIDTH, PADDLE_Y, BALL_R } from './game/neon.js';
// Simulate 30 s of gameplay at 60 fps, level ramps up automatically.
const state = createState(1);
state.lives = 5;
let maxBricksBroken = 0, frames = 0;
for (let i = 0; i < 60 * 30; i++) {
  const dt = 1 / 60;
  const broken = tick(state, dt);
  maxBricksBroken = Math.max(maxBricksBroken, broken);
  frames++;
  const v = Math.hypot(state.ball.vx, state.ball.vy);
  // after the first paddle touch, norm must be exactly ballSpeed(level)
  const speed = ballSpeed(state.level);
  if (Math.abs(v - speed) > 0.01 && state.level >= 1) {
    // launch has a different norm; only flag once the paddle has been touched
    if (state.combo === 0 && state.ball.vy < 0 && state.ball.y < 200) { /* ok */ }
  }
}
console.log('frames simulated:', frames);
console.log('level reached:', state.level, '| lives:', state.lives, '| score:', state.score);
console.log('ball speed norm:', Math.hypot(state.ball.vx, state.ball.vy).toFixed(2), '| level speed:', ballSpeed(state.level));
console.log('ball in bounds:', state.ball.x - state.ball.r >= 0 && state.ball.x + state.ball.r <= WIDTH && state.ball.y > 0);
"

