// --- Brick collision (swept + discrete) ------------------------------------

// Swept test: does the segment (fx,fy)->(tx,ty) enter the rect
// (x0,y0)-(x1,y1)? Returns the earliest entry time t in (0,1] and the face
// that was crossed ('top' | 'bottom' | 'left' | 'right'), or null when there
// is no crossing (the ball started inside or never touched the rect).
function sweptEntry(fx, fy, tx, ty, x0, y0, x1, y1) {
  const dx = tx - fx;
  const dy = ty - fy;
  if (dx === 0 && dy === 0) return null;

  let tmin = 0;
  let tmax = 1;
  let face = null;

  if (dx === 0) {
    if (fx <= x0 || fx >= x1) return null;
  } else {
    const t1 = (x0 - fx) / dx;
    const t2 = (x1 - fx) / dx;
    const entry = Math.min(t1, t2);
    const exit = Math.max(t1, t2);
    if (entry > tmin) {
      tmin = entry;
      face = dx > 0 ? 'left' : 'right';
    }
    if (exit < tmax) tmax = exit;
  }

  if (dy === 0) {
    if (fy <= y0 || fy >= y1) return null;
  } else {
    const t1 = (y0 - fy) / dy;
    const t2 = (y1 - fy) / dy;
    const entry = Math.min(t1, t2);
    const exit = Math.max(t1, t2);
    if (entry > tmin) {
      tmin = entry;
      face = dy > 0 ? 'top' : 'bottom';
    }
    if (exit < tmax) tmax = exit;
  }

  if (tmin > tmax || tmin <= 0 || tmin > 1) return null;
  return { t: tmin, face };
}

