import { createState, tick, ballSpeed, WIDTH, HEIGHT, BALL_R } from './game/neon.js';
let bad = 0, minV = Infinity;
for (let seed = 0; seed < 40; seed++) {
  const state = createState(1 + (seed % 12));
  state.lives = 9;
  // random paddle position each frame, like a mouse
  let paddle = (WIDTH - 96) / 2;
  for (let i = 0; i < 1200; i++) {
    paddle = ((paddle * 2654435761 + seed * 97) % (WIDTH - 96)) + 0; // deterministic wiggle
    state.paddle.x = Math.max(0, Math.min(WIDTH - state.paddle.w, paddle));
    tick(state, 1 / 60 + (i % 3) * 0.01); // varied dt up to the cap
    const b = state.ball;
    if (![b.x, b.y, b.vx, b.vy].every(Number.isFinite)) { bad++; break; }
    if (b.y - BALL_R > HEIGHT + 5 || b.x - BALL_R < -5 || b.x + BALL_R > WIDTH + 5) { bad++; break; }
    const v = Math.hypot(b.vx, b.vy);
    if (v > 0) minV = Math.min(minV, v);
  }
}
console.log('anomalies:', bad, '| min speed observed:', minV.toFixed(2));
